    # Replace every source cell by its 2x2 enlargement; nonzero cells use checkerboard 1/2.
    h=len(grid); w=len(grid[0])
    out=[[0]*(2*w) for _ in range(2*h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                out[2*r][2*c]=1; out[2*r][2*c+1]=2
                out[2*r+1][2*c]=2; out[2*r+1][2*c+1]=1
    return out"}

